// Capture throughput index — record JAH-GPCS-CAPTURECARD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"max_res_mp": 8.3, "fps": 60, "latency_ms": 50};
var value = (m.max_res_mp*m.fps/m.latency_ms);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-CAPTURECARD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-CAPTURECARD-000001|' + value.toFixed(2) + ' throughput index');

